@startuml

class Person {}

class Student extends Person {
  + name : string
  + email : string
}

class Tutor extends Person {
  + name : string
  + email : string
  + bankAccount : string
}

class Subject {}

class ExpertiseLevel {}

class TutoringOffer {
  + hourlyPrice : float
}

class Availability {
  + day : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + level : string
  + targetDate : date
  + targetTime : time
}

class TutoringSession {
  + actualDate : date
  + actualTime : time
  + isFollowUp : boolean
  + status : string
}

class Payment {
  + amount : float
  + method : string
}

class Award {
  + month : string
}

Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringRequest : receives
Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" Availability : specifies
Tutor "1" -- "*" TutoringOffer : subject
Subject "1" -- "*" TutoringOffer : belongs to
TutoringRequest "1" -- "0..1" TutoringSession : becomes
Student "1" -- "*" TutoringSession : attends
Tutor "1" -- "*" TutoringSession : conducts
TutoringSession "1" -- "0..1" Payment : results in
Tutor "1" -- "*" Award : receives
Subject "1" -- "*" Award : awarded for

@enduml

